def getItems(workspace_id, collection, fields=None, filter=None, sort=None, limit=None, offset=None, page=None, page_size=None, search=None, deep=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0277000" if __import__("os").path.isdir("./environment_mix/0277000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex

    def _log_and_return(status, ws_id, api_key_id, coll, item_id, payload, resp_status, resp_body, err_msg, body):
        duration_ms = int((time.time() - start) * 1000)
        tool_calls = _load("tool_calls.json")
        tc = {
            "id": _new_id("dmp_tc_"),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "tool_name": "getItems",
            "collection_name": coll,
            "directus_item_id": item_id,
            "request_payload_json": payload if isinstance(payload, dict) else {},
            "response_status_code": resp_status,
            "response_body_json": resp_body,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return body

    payload = {
        "workspace_id": workspace_id,
        "collection": collection,
    }
    if fields is not None: payload["fields"] = fields
    if filter is not None: payload["filter"] = filter
    if sort is not None: payload["sort"] = sort
    if limit is not None: payload["limit"] = limit
    if offset is not None: payload["offset"] = offset
    if page is not None: payload["page"] = page
    if page_size is not None: payload["page_size"] = page_size
    if search is not None: payload["search"] = search
    if deep is not None: payload["deep"] = deep

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^dmp_ws_[0-9A-Z]{18,}$", workspace_id or ""):
        return _log_and_return("rejected", workspace_id if isinstance(workspace_id, str) else "unknown", None, collection if isinstance(collection, str) else None, None,
                               payload, None, None, "Invalid workspace_id format", _err("VALIDATION_ERROR", "Invalid workspace_id format"))
    if not isinstance(collection, str) or not collection:
        return _log_and_return("rejected", workspace_id, None, None, None, payload, None, None, "Invalid collection", _err("VALIDATION_ERROR", "collection must be a non-empty string"))
    if fields is not None and (not isinstance(fields, list) or any(not isinstance(x, str) for x in fields)):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid fields", _err("VALIDATION_ERROR", "fields must be an array of strings"))
    if sort is not None and (not isinstance(sort, list) or any(not isinstance(x, str) for x in sort)):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid sort", _err("VALIDATION_ERROR", "sort must be an array of strings"))
    if filter is not None and not isinstance(filter, dict):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid filter", _err("VALIDATION_ERROR", "filter must be an object"))
    if deep is not None and not isinstance(deep, dict):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid deep", _err("VALIDATION_ERROR", "deep must be an object"))
    if search is not None and not isinstance(search, str):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid search", _err("VALIDATION_ERROR", "search must be a string"))
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid limit", _err("VALIDATION_ERROR", "limit must be an integer >= 1"))
    if offset is not None and (not isinstance(offset, int) or offset < 0):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid offset", _err("VALIDATION_ERROR", "offset must be an integer >= 0"))
    if page is not None and (not isinstance(page, int) or page < 1):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid page", _err("VALIDATION_ERROR", "page must be an integer >= 1"))
    if page_size is not None and (not isinstance(page_size, int) or page_size < 1):
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid page_size", _err("VALIDATION_ERROR", "page_size must be an integer >= 1"))

    # Pagination style validation
    uses_offset_style = (limit is not None) or (offset is not None)
    uses_page_style = (page is not None) or (page_size is not None)
    if uses_offset_style and uses_page_style:
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None,
                               "Cannot mix offset/limit with page/page_size", _err("VALIDATION_ERROR", "Cannot mix offset+limit with page+page_size"))

    # Resolve an authorized workspace+key combination (ambient auth)
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _log_and_return("failed", workspace_id, None, collection, None, payload, None, None, "Workspace not found", _err("NOT_FOUND", "Workspace not found"))

    api_keys = _load("api_keys.json")
    def _parse_dt(s):
        if not s: return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    chosen_key = None
    # choose a working key if any; otherwise allow if none exist (ambient auth)
    candidates = [k for k in api_keys if k.get("workspace_id") == workspace_id]
    active_candidates = []
    for k in candidates:
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp and exp <= datetime.datetime.utcnow():
            continue
        scopes = k.get("scopes") if isinstance(k.get("scopes"), list) else []
        if "getItems" not in scopes:
            continue
        active_candidates.append(k)
    if active_candidates:
        chosen_key = active_candidates[0]
        # update last_used_at
        for k in api_keys:
            if k.get("id") == chosen_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)
    # If there are keys for this workspace but none can authorize, reject.
    if candidates and not chosen_key:
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None,
                               "No active API key with required scope", _err("UNAUTHORIZED", "API key invalid/expired/revoked or missing required scope"))

    # Workspace must be active for successful operations
    if ws.get("status") != "active":
        return _log_and_return("rejected", workspace_id, chosen_key.get("id") if chosen_key else None, collection, None, payload, None, None,
                               "Workspace not active", _err("UNAUTHORIZED", "Workspace is not active"))

    # Enforce workspace max_page_size
    max_page_size = ws.get("max_page_size")
    if not isinstance(max_page_size, int) or max_page_size < 1:
        max_page_size = 5000
    eff_limit = None
    eff_offset = 0
    if uses_page_style:
        eff_page_size = page_size if page_size is not None else None
        eff_page = page if page is not None else 1
        if eff_page_size is None:
            eff_page_size = min(100, max_page_size)
        eff_page_size = min(eff_page_size, max_page_size)
        eff_limit = eff_page_size
        eff_offset = (eff_page - 1) * eff_page_size
    elif uses_offset_style:
        eff_limit = limit if limit is not None else None
        if eff_limit is None:
            eff_limit = min(100, max_page_size)
        eff_limit = min(eff_limit, max_page_size)
        eff_offset = offset if offset is not None else 0
    else:
        eff_limit = min(100, max_page_size)
        eff_offset = 0

    # Read from local indexed items; treat as present items in the collection
    items_index = _load("items_index.json")
    present = [r for r in items_index if r.get("workspace_id") == workspace_id and r.get("collection_name") == collection and r.get("status") == "present"]

    # Apply search (against id as string) and basic filter support on directus_item_id
    if search:
        s = search.lower()
        present = [r for r in present if s in str(r.get("directus_item_id", "")).lower()]

    def _matches_filter(row, fobj):
        # very small subset: { "directus_item_id": {"_eq": "x"} } or {"directus_item_id":{"_in":[...]}} or {"directus_item_id":"x"}
        if not isinstance(fobj, dict) or not fobj:
            return True
        for k, v in fobj.items():
            if k != "directus_item_id":
                continue
            rid = str(row.get("directus_item_id"))
            if isinstance(v, dict):
                if "_eq" in v:
                    return rid == str(v["_eq"])
                if "_in" in v and isinstance(v["_in"], list):
                    return rid in [str(x) for x in v["_in"]]
            else:
                return rid == str(v)
        return True

    if filter:
        present = [r for r in present if _matches_filter(r, filter)]

    # Apply sort by directus_item_id or last_seen_at/updated_at if requested
    if sort:
        def _key_for(field, row):
            if field in ("directus_item_id", "id"):
                return str(row.get("directus_item_id", ""))
            if field in ("last_seen_at", "updated_at", "created_at"):
                return str(row.get(field) or "")
            return str(row.get(field) or "")
        # apply in reverse order for stable multi-sort
        for sfield in reversed(sort):
            desc = isinstance(sfield, str) and sfield.startswith("-")
            fname = sfield[1:] if desc else sfield
            present.sort(key=lambda r, f=fname: _key_for(f, r), reverse=desc)

    total = len(present)
    page_rows = present[eff_offset:eff_offset + eff_limit] if eff_limit is not None else present[eff_offset:]
    has_more = (eff_offset + len(page_rows)) < total
    next_cursor = str(eff_offset + len(page_rows)) if has_more else None

    # "Return resulting item array" - we only have ids in datastore; return minimal item objects with id
    items = [{"id": r.get("directus_item_id")} for r in page_rows]

    # Upsert items_index last_seen_at for observed items
    if items:
        idx_map = {(r.get("workspace_id"), r.get("collection_name"), r.get("directus_item_id")): r for r in items_index}
        mutated = False
        for it in items:
            did = str(it.get("id"))
            key = (workspace_id, collection, did)
            row = idx_map.get(key)
            if row:
                if row.get("status") != "present":
                    row["status"] = "present"
                row["last_seen_at"] = now
                row["updated_at"] = now
                mutated = True
            else:
                newr = {
                    "id": _new_id("dmp_itx_"),
                    "workspace_id": workspace_id,
                    "collection_name": collection,
                    "directus_item_id": did,
                    "last_seen_at": now,
                    "last_mutation_at": None,
                    "status": "present",
                    "created_at": now,
                    "updated_at": now,
                }
                items_index.append(newr)
                idx_map[key] = newr
                mutated = True
        if mutated:
            _save("items_index.json", items_index)

    body = {
        "data": items,
        "meta": {
            "total": total,
            "limit": eff_limit,
            "offset": eff_offset,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
    return _log_and_return("succeeded", workspace_id, chosen_key.get("id") if chosen_key else None, collection, None, payload, 200, {"count": len(items)}, None, body)

def createItem(workspace_id, collection, data, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0277000" if __import__("os").path.isdir("./environment_mix/0277000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex

    def _log_and_return(status, ws_id, api_key_id, coll, item_id, payload, resp_status, resp_body, err_msg, body):
        duration_ms = int((time.time() - start) * 1000)
        tool_calls = _load("tool_calls.json")
        tc = {
            "id": _new_id("dmp_tc_"),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "tool_name": "createItem",
            "collection_name": coll,
            "directus_item_id": item_id,
            "request_payload_json": payload if isinstance(payload, dict) else {},
            "response_status_code": resp_status,
            "response_body_json": resp_body,
            "error_message": err_msg,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(tc)
        _save("tool_calls.json", tool_calls)
        return body

    payload = {"workspace_id": workspace_id, "collection": collection, "data": data}

    if not isinstance(workspace_id, str) or not re.match(r"^dmp_ws_[0-9A-Z]{18,}$", workspace_id or ""):
        return _log_and_return("rejected", workspace_id if isinstance(workspace_id, str) else "unknown", None, collection if isinstance(collection, str) else None, None,
                               payload, None, None, "Invalid workspace_id format", _err("VALIDATION_ERROR", "Invalid workspace_id format"))
    if not isinstance(collection, str) or not collection:
        return _log_and_return("rejected", workspace_id, None, None, None, payload, None, None, "Invalid collection", _err("VALIDATION_ERROR", "collection must be a non-empty string"))
    if not isinstance(data, dict) or data is None:
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None, "Invalid data", _err("VALIDATION_ERROR", "data must be an object"))

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _log_and_return("failed", workspace_id, None, collection, None, payload, None, None, "Workspace not found", _err("NOT_FOUND", "Workspace not found"))

    api_keys = _load("api_keys.json")
    def _parse_dt(s):
        if not s: return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    chosen_key = None
    candidates = [k for k in api_keys if k.get("workspace_id") == workspace_id]
    active_candidates = []
    for k in candidates:
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp and exp <= datetime.datetime.utcnow():
            continue
        scopes = k.get("scopes") if isinstance(k.get("scopes"), list) else []
        if "createItem" not in scopes:
            continue
        active_candidates.append(k)
    if active_candidates:
        chosen_key = active_candidates[0]
        for k in api_keys:
            if k.get("id") == chosen_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)
    if candidates and not chosen_key:
        return _log_and_return("rejected", workspace_id, None, collection, None, payload, None, None,
                               "No active API key with required scope", _err("UNAUTHORIZED", "API key invalid/expired/revoked or missing required scope"))
    if ws.get("status") != "active":
        return _log_and_return("rejected", workspace_id, chosen_key.get("id") if chosen_key else None, collection, None, payload, None, None,
                               "Workspace not active", _err("UNAUTHORIZED", "Workspace is not active"))

    # Create "Directus item" locally by creating an index row; id can be provided in payload as 'id'
    directus_item_id = None
    if "id" in data and data["id"] is not None:
        if not isinstance(data["id"], (str, int)):
            return _log_and_return("rejected", workspace_id, chosen_key.get("id") if chosen_key else None, collection, None, payload, None, None,
                                   "Invalid data.id", _err("VALIDATION_ERROR", "data.id must be a string or integer if provided"))
        directus_item_id = str(data["id"])
    else:
        directus_item_id = uuid.uuid4().hex  # plausible Directus-like id

    items_index = _load("items_index.json")
    # uniqueness: (workspace_id, collection_name, directus_item_id)
    existing = next((r for r in items_index if r.get("workspace_id") == workspace_id and r.get("collection_name") == collection and str(r.get("directus_item_id")) == directus_item_id), None)
    if existing and existing.get("status") == "present":
        return _log_and_return("failed", workspace_id, chosen_key.get("id") if chosen_key else None, collection, directus_item_id, payload, 409, None,
                               "Item already exists", _err("CONFLICT", "Item with this id already exists"))
    # Upsert index row as present and set last_mutation_at
    if existing:
        existing["status"] = "present"
        existing["last_mutation_at"] = now
        existing["last_seen_at"] = existing.get("last_seen_at") or now
        existing["updated_at"] = now
    else:
        items_index.append({
            "id": _new_id("dmp_itx_"),
            "workspace_id": workspace_id,
            "collection_name": collection,
            "directus_item_id": directus_item_id,
            "last_seen_at": now,
            "last_mutation_at": now,
            "status": "present",
            "created_at": now,
            "updated_at": now,
        })
    _save("items_index.json", items_index)

    created_item = dict(data)
    created_item["id"] = directus_item_id
    return _log_and_return("succeeded", workspace_id, chosen_key.get("id") if chosen_key else None, collection, directus_item_id, payload, 201, {"id": directus_item_id}, None, {"data": created_item})

def deleteItem(workspace_id, collection, id, **_extra):
    import json, os, datetime, time, re, uuid

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0277000" if __import__("os").path.isdir("./environment_mix/0277000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _duration_ms():
        return int((time.time() - _t0) * 1000)

    def _new_id(prefix):
        return prefix + uuid.uuid4().hex

    payload = {"workspace_id": workspace_id, "collection": collection, "id": id}

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
    items_index = _load("items_index.json")

    ws_for_log = None
    if isinstance(workspace_id, str):
        ws_for_log = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws_for_log is None:
        ws_for_log = next((w for w in workspaces if isinstance(w, dict) and w.get("id")), None)

    def _append_tool_call(status, ws_id, api_key_id, resp_status=None, resp_body=None, err_msg=None):
        if not ws_id:
            return
        row = {
            "id": _new_id("dmp_tc_"),
            "workspace_id": ws_id,
            "api_key_id": api_key_id,
            "tool_name": "deleteItem",
            "collection_name": collection if isinstance(collection, str) else None,
            "directus_item_id": id if isinstance(id, str) else None,
            "request_payload_json": payload if isinstance(payload, dict) else {},
            "response_status_code": resp_status,
            "response_body_json": resp_body,
            "error_message": err_msg,
            "duration_ms": _duration_ms(),
            "status": status,
            "created_at": _now(),
            "updated_at": _now(),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^dmp_ws_[0-9A-Z]{18,}$", workspace_id or ""):
        _append_tool_call("rejected", ws_for_log["id"] if ws_for_log else None, None, None, None, "Invalid workspace_id format")
        return _err("VALIDATION_ERROR", "Invalid workspace_id format")
    if not isinstance(collection, str) or not collection.strip():
        _append_tool_call("rejected", workspace_id, None, None, None, "collection must be a non-empty string")
        return _err("VALIDATION_ERROR", "collection must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _append_tool_call("rejected", workspace_id, None, None, None, "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        _append_tool_call("failed", ws_for_log["id"] if ws_for_log else None, None, None, None, "Workspace not found")
        return _err("NOT_FOUND", "Workspace not found")

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    api_key = None
    for k in api_keys if isinstance(api_keys, list) else []:
        if not isinstance(k, dict):
            continue
        if k.get("workspace_id") != workspace_id:
            continue
        if k.get("status") != "active":
            continue
        exp = _parse_dt(k.get("expires_at"))
        if exp is not None and exp <= now_dt:
            continue
        scopes = k.get("scopes")
        if not isinstance(scopes, list) or "deleteItem" not in scopes:
            continue
        api_key = k
        break
    if api_key is None:
        _append_tool_call("rejected", workspace_id, None, None, None, "No active API key with scope deleteItem available for this workspace")
        return _err("UNAUTHORIZED", "No active API key with scope deleteItem available for this workspace")

    # If catalog exists for workspace, require collection to be present there.
    catalog = _load("collections_catalog.json")
    ws_catalog = [c for c in catalog if isinstance(c, dict) and c.get("workspace_id") == workspace_id]
    if ws_catalog and not any(c.get("collection_name") == collection for c in ws_catalog):
        _append_tool_call("failed", workspace_id, api_key.get("id"), None, None, "Collection not found")
        return _err("NOT_FOUND", "Collection not found")

    # Deletion effect: set items_index status=deleted (create if absent)
    now_s = _now()
    idx = next(
        (
            r for r in items_index
            if isinstance(r, dict)
            and r.get("workspace_id") == workspace_id
            and r.get("collection_name") == collection
            and r.get("directus_item_id") == id
        ),
        None,
    )
    if idx is None:
        # create then mark deleted
        idx = {
