def createWorkspace(name, directus_base_url, status=None, request_timeout_ms=None, max_page_size=None, **_extra):
    import json, os, datetime, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0277000" if __import__("os").path.isdir("./environment_mix/0277000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id():
        # Match datastore style prefixes while staying deterministic enough
        return "dmp_ws_" + uuid.uuid4().hex.upper()

    def _is_valid_url(u):
        if not isinstance(u, str) or not u.strip():
            return False
        p = urlparse(u.strip())
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _norm_url(u):
        u = u.strip()
        while u.endswith("/"):
            u = u[:-1]
        return u

    # --- validate per tool schema ---
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string")
    if not isinstance(directus_base_url, str) or not directus_base_url.strip():
        return _err("VALIDATION_ERROR", "directus_base_url must be a non-empty string")
    if not _is_valid_url(directus_base_url):
        return _err("VALIDATION_ERROR", "directus_base_url must be a valid http(s) URL")

    if status is None:
        status = "active"
    if status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled, error")

    # Tool schema allows wider ranges than workspace constraints; enforce datastore constraints (1000..120000, 1..5000)
    if request_timeout_ms is None:
        request_timeout_ms = 45000
    if not isinstance(request_timeout_ms, int):
        return _err("VALIDATION_ERROR", "request_timeout_ms must be an integer")
    if request_timeout_ms < 1000 or request_timeout_ms > 120000:
        return _err(
            "VALIDATION_ERROR",
            "request_timeout_ms violates workspace constraint: request_timeout_ms >= 1000 AND request_timeout_ms <= 120000",
            request_timeout_ms=request_timeout_ms,
        )

    if max_page_size is None:
        max_page_size = 500
    if not isinstance(max_page_size, int):
        return _err("VALIDATION_ERROR", "max_page_size must be an integer")
    if max_page_size < 1 or max_page_size > 5000:
        return _err(
            "VALIDATION_ERROR",
            "max_page_size violates workspace constraint: max_page_size >= 1 AND max_page_size <= 5000",
            max_page_size=max_page_size,
        )

    workspaces = _load("workspaces.json")
    norm = _norm_url(directus_base_url)

    # Uniqueness constraint: unique(directus_base_url) with normalization
    for w in workspaces:
        if not isinstance(w, dict):
            continue
        existing = w.get("directus_base_url")
        if isinstance(existing, str) and _norm_url(existing) == norm:
            return _err(
                "CONFLICT",
                "directus_base_url must be unique (constraint unique(directus_base_url))",
                directus_base_url=directus_base_url,
            )

    now_iso = _now()
    new_ws = {
        "id": _new_id(),
        "name": name.strip(),
        "directus_base_url": norm,
        "status": status,
        "last_healthcheck_at": None,
        "last_error": None,
        "request_timeout_ms": request_timeout_ms,
        "max_page_size": max_page_size,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    workspaces.append(new_ws)
    _save("workspaces.json", workspaces)
    return {"data": new_ws}

